$(document).ready(function(e){if($(".selectJS").length){function t(e){if(!e.id)return e.text;var t=$(e.element).data("flag"),i=$(`<div style="display: flex; align-items: center; padding: 5px;">\n          <img src="${t}" style="width: 30px; height: 30px; border-radius: 50%; margin-right: 10px;" />\n          <span>${e.text}</span>\n        </div>`);return i}$(".selectJS").select2({placeholder:"Search for country",templateResult:t,tag:!0,templateSelection:t,width:"100%"})}$(".leftToRightSlider").length&&$(".leftToRightSlider").slick({slidesToShow:4,slidesToScroll:1,autoplay:!0,arrow:!1,dots:!1,infinite:!0,autoplaySpeed:2e3,centerMode:!1,variableWidth:!0,responsive:[{breakpoint:768,settings:{slidesToShow:2}},{breakpoint:480,settings:{slidesToShow:1}}]})});